def design(x, f, kind):
    cols = [np.ones(len(x))]
    if kind.startswith('lin'):
        cols.append(x)
    cols.append(np.sin(x * f[:4] + (f[4:] if kind.endswith('phase') else 0)))
    if kind.endswith('cos'):
        cols.append(np.cos(x * f[:4]))
    return np.column_stack(cols)

def fit(a, b, kind, starts):
    from scipy.optimize import least_squares

    def solve(f):
        d = design(a, f, kind)
        w = np.linalg.lstsq(d, b, rcond=None)[0]
        return ((d @ w - b).ravel(), w)
    best = None
    for f in starts:
        if kind.endswith('phase'):
            f = np.r_[f, np.zeros(4)]
        low = np.r_[np.full(4, 0.1), np.full(len(f) - 4, -np.pi)]
        high = np.r_[np.full(4, 8.0), np.full(len(f) - 4, np.pi)]
        r = least_squares(lambda p: solve(p)[0], f, bounds=(low, high), max_nfev=150, gtol=1e-11)
        (err, w) = solve(r.x)
        rmse = np.mean(err ** 2) ** 0.5
        if best is None or rmse < best[0]:
            best = (rmse, r.x, w)
    return best

def _coordinates(x, calibration):
    (offset, gain, mixing) = calibration
    return _affine((x - offset) / gain) @ mixing

def _relaxation(design, trajectories, times):
    from scipy.optimize import least_squares
    (q, r) = np.linalg.qr(design, mode='reduced')
    projected = q.T @ trajectories

    def basis(log_rates):
        return -np.expm1(-times[:, None] * np.exp(log_rates))

    def residual(log_rates):
        b = basis(log_rates)
        return (b @ _ls(b, projected.T) - projected.T).ravel()
    result = least_squares(residual, np.log([0.4, 1.8]), bounds=(np.log(0.03), np.log(15.0)))
    b = basis(result.x)
    weights = _ls(r, _ls(b, projected.T).T)
    return weights @ b.T
